import 'package:igniteui_flutter_core/src/ArrayList.dart' show ArrayList;
import 'package:igniteui_flutter_core/src/reflection.dart' show IReflectable, IReflectableSet;

// The keys stay as the C# and TypeScript spell them: a data item defined in
// code keeps its own casing across platforms, and these are the names the
// member paths in the descriptions ask for.
class SalesEmbeddedItem implements IReflectable, IReflectableSet {
    String? country = null;
    String? product = null;
    String? unitsSold = null;
    double manufacturingPrice = 0;
    double salePrice = 0;
    double grossSales = 0;
    double discounts = 0;
    double sales = 0;
    double cogs = 0;
    double profit = 0;
    String? date = null;
    String? monthName = null;
    String? year = null;

    Object? getValue(String? propertyName) {
        switch (propertyName) {
            case "Country":
                return this.country;
            case "Product":
                return this.product;
            case "UnitsSold":
                return this.unitsSold;
            case "ManufacturingPrice":
                return this.manufacturingPrice;
            case "SalePrice":
                return this.salePrice;
            case "GrossSales":
                return this.grossSales;
            case "Discounts":
                return this.discounts;
            case "Sales":
                return this.sales;
            case "COGS":
                return this.cogs;
            case "Profit":
                return this.profit;
            case "Date":
                return this.date;
            case "MonthName":
                return this.monthName;
            case "Year":
                return this.year;
        }
        return null;
    }

    void setValue(String? propertyName, Object? value) {
        switch (propertyName) {
            case "Country":
                this.country = value as String?;
                break;
            case "Product":
                this.product = value as String?;
                break;
            case "UnitsSold":
                this.unitsSold = value as String?;
                break;
            case "ManufacturingPrice":
                this.manufacturingPrice = (value as num).toDouble();
                break;
            case "SalePrice":
                this.salePrice = (value as num).toDouble();
                break;
            case "GrossSales":
                this.grossSales = (value as num).toDouble();
                break;
            case "Discounts":
                this.discounts = (value as num).toDouble();
                break;
            case "Sales":
                this.sales = (value as num).toDouble();
                break;
            case "COGS":
                this.cogs = (value as num).toDouble();
                break;
            case "Profit":
                this.profit = (value as num).toDouble();
                break;
            case "Date":
                this.date = value as String?;
                break;
            case "MonthName":
                this.monthName = value as String?;
                break;
            case "Year":
                this.year = value as String?;
                break;
        }
    }
}

